def test_size_cap_all_routes_without_reading_body(api, method, target):
    auth = api.auth()
    header_text = "".join(f"{key}: {value}\r\n" for key, value in {**auth, **ADMIN}.items())
    # Deliberately send no body: a handler that reads before rejecting hangs.
    reply = raw_request(api.port, (
        f"{method} {target} HTTP/1.1\r\n{header_text}Content-Length: 8193\r\n\r\n"
    ).encode())
    assert reply[0] == 413 and error_code(reply) == "payload_too_large"
    assert reply[1][b"Connection"] == b"close"


